/**
 * Room registry: every 3D world room by id. A room definition is plain data
 * (rooms/<room>.js): its GLB, the layout generated by its Blender build script
 * (colliders, seats, spawn points, floors, hero camera, anchors), the look (colour
 * grade, emissive levels, avatar lights) and optional runtime effects / props.
 * WorldEngine loads a room by id; switching rooms (UI, protocol) is a later phase.
 */
import livingRoom from "./livingRoom.js";
import cinema from "./cinema.js";
import gameRoom from "./gameRoom.js";
import camp from "./camp.js";

export const ROOMS = { [livingRoom.id]: livingRoom, [cinema.id]: cinema, [gameRoom.id]: gameRoom, [camp.id]: camp };
export const ROOM_IDS = Object.keys(ROOMS);
export const DEFAULT_ROOM = livingRoom.id;

export function getRoom(id) {
  return ROOMS[id] || ROOMS[DEFAULT_ROOM];
}
